#include <stdio.h>

/* 计算长度为 n 的顺序表，在每一个可能位置插入时的搬移次数。
 * 在下标 p 插入，需要把 p..n-1 的元素整体后移一位 → 搬移 n - p 个。 */
int main(void) {
    int n = 8;
    long total = 0;
    for (int p = 0; p <= n; p++) {
        int shifts = n - p;
        total += shifts;
        printf("在下标 %d 插入：搬移 %d 个元素\n", p, shifts);
    }
    printf("合计搬移 = %ld 次（n = %d）\n", total, n);
    printf("平均每次插入搬移 = %.1f 个（约为 n/2）\n", (double)total / (n + 1));
    printf("结论：头插最坏 O(n)，尾插 O(1)，平均 O(n)\n");
    return 0;
}
